#!/usr/bin/env node
// Writes the token files from src/tokens/tokens.js (Plan 3 · P3-2.02). Run: npm run tokens
// --check exits 1 when a generated file is out of date (used by CI and tokens.test.js).
const fs = require('fs');
const path = require('path');

const tokens = require('../src/tokens/tokens');

const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').replace(/([a-z])([0-9])/g, '$1-$2').toLowerCase();
const HEADER = '/* Generated by scripts/build-tokens.js from src/tokens/tokens.js. Do not edit. */\n';

function cssVariables() {
  const lines = [];
  Object.entries(tokens.palette).forEach(([name, scale]) => {
    Object.entries(scale).forEach(([step, value]) => lines.push(`--elmp-${name}-${step}: ${value};`));
  });
  Object.entries(tokens.color).forEach(([k, v]) => lines.push(`--cls-${kebab(k)}: ${v};`));
  Object.entries(tokens.covers).forEach(([k, [a, b]]) => lines.push(`--cls-cover-${k}: linear-gradient(135deg, ${a} 0%, ${b} 100%);`));
  lines.push(`--cls-font: ${tokens.font.sans};`, `--cls-font-mono: ${tokens.font.mono};`);
  Object.entries(tokens.radius).forEach(([k, v]) => lines.push(`--cls-radius-${k}: ${v};`));
  Object.entries(tokens.shadow).forEach(([k, v]) => lines.push(`--cls-shadow-${k}: ${v};`));
  Object.entries(tokens.motion).forEach(([k, v]) => lines.push(`--cls-${k.startsWith('ease') ? kebab(k) : `dur-${k}`}: ${v};`));
  Object.entries(tokens.size).forEach(([k, v]) => lines.push(`--cls-size-${kebab(k)}: ${v};`));
  return lines;
}

function tokensCss() {
  return `${HEADER}:root {\n${cssVariables().map((l) => `  ${l}`).join('\n')}\n}\n`;
}

function tokensScss() {
  const lines = Object.entries(tokens.color).map(([k, v]) => `$cls-${kebab(k)}: ${v};`);
  Object.entries(tokens.size).forEach(([k, v]) => lines.push(`$cls-size-${kebab(k)}: ${v};`));
  lines.push('$cls-bp-md: 768px;', '$cls-bp-lg: 1024px;', '$cls-bp-xl: 1280px;');
  return `${HEADER.replace('/*', '//').replace(' */', '')}${lines.join('\n')}\n`;
}

// Paragon 23 runtime theme (doc 04 §7). Loaded by the apps through PARAGON_THEME_URLS.
function paragonCss() {
  const { green } = tokens.palette;
  const { color, font, radius } = tokens;
  const scale = (prefix) => [100, 200, 300, 400, 500, 600, 700, 800, 900]
    .map((s) => `--pgn-color-${prefix}-${s}: ${green[s]};`);
  const lines = [
    `--pgn-color-primary-base: ${color.action};`,
    `--pgn-color-primary-light: ${color.actionTint};`,
    ...scale('primary'),
    `--pgn-color-brand-base: ${color.action};`,
    ...scale('brand'),
    `--pgn-color-accent-a: ${tokens.palette.gold[500]};`,
    `--pgn-color-accent-b: ${tokens.palette.gold[100]};`,
    `--pgn-typography-font-family-base: ${font.sans};`,
    `--pgn-typography-font-family-sans-serif: ${font.sans};`,
    `--pgn-size-border-radius-sm: ${radius.xs};`,
    `--pgn-size-border-radius-base: ${radius.button};`,
    `--pgn-size-border-radius-lg: ${radius.card};`,
  ];
  return `${HEADER}:root {\n${lines.map((l) => `  ${l}`).join('\n')}\n}\n`;
}

const outputs = {
  'src/tokens/tokens.css': tokensCss(),
  'src/tokens/_tokens.scss': tokensScss(),
  'src/tokens/paragon-theme.css': paragonCss(),
};

module.exports = { outputs };

if (require.main === module) {
  const root = path.join(__dirname, '..');
  const check = process.argv.includes('--check');
  let stale = 0;
  Object.entries(outputs).forEach(([file, content]) => {
    const target = path.join(root, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
    if (current === content) { return; }
    if (check) {
      stale += 1;
      process.stderr.write(`out of date: ${file}\n`);
    } else {
      fs.writeFileSync(target, content);
      process.stdout.write(`wrote ${file}\n`);
    }
  });
  process.exit(stale ? 1 : 0);
}
